  function home() { const owner = role(); return `<section class="ifspace-page"><header class="ifspace-header"><div><span>平行时空</span><h1>if 时空</h1><p>去看看，另一种人生会怎样。</p></div><button class="ifspace-close" type="button" data-if-close aria-label="关闭">×</button></header><main class="ifspace-main"><section class="ifspace-hero"><div class="ifspace-cosmos" aria-hidden="true"><i class="ifspace-orbit orbit-one"></i><i class="ifspace-orbit orbit-two"></i><i class="ifspace-orbit orbit-three"></i><b class="ifspace-star star-one">✦</b><b class="ifspace-star star-two">·</b><b class="ifspace-star star-three">✶</b></div><div class="ifspace-hero-copy"><small>如果 / 宇宙</small><h2>每一个如果，<br>都是一颗新的星球。</h2><p>每个时空独立运行，不会写入原本的聊天记忆。</p></div><button type="button" data-if-new aria-label="创建一个新时空"><i class="ifspace-new-planet">＋</i><span>创建时空</span><small>新世界</small></button></section><section class="ifspace-owner"><span>参与角色</span><button type="button" data-if-role-picker><i>${avatar(owner)}</i><b>${esc(owner?.nickname || owner?.name || '选择角色')}</b><em>⌄</em></button></section><section class="ifspace-list"><div class="ifspace-section-title"><span>我的宇宙</span><b>${state.spaces.length} 颗行星</b></div>${state.spaces.length ? state.spaces.slice().reverse().map(spaceCard).join('') : '<div class="ifspace-empty-block"><div class="ifspace-empty-system" aria-hidden="true"><span class="ifspace-empty-orbit orbit-a"><i></i></span><span class="ifspace-empty-orbit orbit-b"><i></i></span><b class="ifspace-empty-sun"></b><em class="ifspace-empty-coordinate">00°00′ / 未探索</em></div><div class="ifspace-empty-copy"><span>还没有时空</span><p>你的宇宙尚未命名。<br>从第一个「如果」开始。</p></div></div>'}</section></main></section>${page === 'role-picker' ? rolePicker() : ''}`; }
  function detail(space) { const owner = roles().find(item => item.id === space.roleId) || role(); const roleName = owner?.nickname || owner?.name || '角色'; return `<section class="ifspace-detail"><header><button type="button" data-if-home aria-label="返回">${icon('back')}</button><div><small>时空 / ${esc(space.setting || '平行世界')}</small><h1>${esc(space.title || '未命名时空')}</h1></div><button type="button" data-if-delete="${esc(space.id)}" aria-label="删除时空">×</button></header><main><div class="ifspace-world-card"><div class="ifspace-world-index"><span>世界前提</span><em>编号 ${String(state.spaces.findIndex(item => item.id === space.id) + 1).padStart(2, '0')}</em></div><h2>${esc(space.premise)}</h2><p>${esc(space.opening || '故事从这里开始。')}</p></div><div class="ifspace-character"><i>${avatar(owner)}</i><div><small>角色 / 01</small><b>${esc(roleName)}</b><p>${esc(space.characterNote || '在这个时空里的角色')}</p></div></div><div class="ifspace-transcript-title"><span>对话记录</span><em>${space.messages?.length || 0} 条消息</em></div><div class="ifspace-message-list">${space.messages?.length ? space.messages.map((item, index) => `<article class="ifspace-message ${item.role === 'user' ? 'is-user' : ''}"><span>${item.role === 'user' ? '用户' : esc(roleName)} · ${String(index + 1).padStart(2, '0')}</span><p>${esc(item.content)}</p></article>`).join('') : '<div class="ifspace-empty-chat"><span>00 / 开始</span><p>时空已经建立。<br>和角色说第一句话吧。</p></div>'}</div></main><form class="ifspace-composer" data-if-chat-form><input data-if-chat-input placeholder="在这个时空里说点什么…" aria-label="消息"><button type="submit" aria-label="发送">${icon('send')}</button></form></section>`; }
  function formatDetailParagraphs() { app.querySelectorAll('.ifspace-world-card > p,.ifspace-message > p').forEach(source => { const parts = source.textContent.split(/\n+/).map(text => text.trim()).filter(Boolean); if (parts.length < 2) return; source.replaceWith(...parts.map(text => { const paragraph = document.createElement('p'); paragraph.textContent = text; return paragraph; })); }); }
  function typographyFor(space) { return { font:space?.typography?.font || 'serif', size:Math.max(12, Math.min(32, Number(space?.typography?.size) || 15)), color:/^#[0-9a-f]{6}$/i.test(space?.typography?.color || '') ? space.typography.color : '#111111', customFontName:space?.typography?.customFontName || '', customFontSource:space?.typography?.customFontSource || '' }; }
