  function loadingPage() { return `<section class="ifspace-loading" role="status" aria-live="polite"><div class="ifspace-loading-window" aria-hidden="true"><span class="ifspace-loading-index">IF / 00</span><i class="ifspace-loading-star star-a"></i><i class="ifspace-loading-star star-b"></i><i class="ifspace-loading-star star-c"></i><i class="ifspace-loading-star star-d"></i><div class="ifspace-loading-planet"><b></b></div><em>生成坐标中</em></div><small>正在建立新的时间线</small><h1>宇宙正在展开</h1><p>正在整理世界设定、人物关系与故事开场<br>生成完成后会自动进入这个时空</p><div class="ifspace-loading-progress"><i></i></div></section>`; }
  function restoreCreateDraft() { if (!createDraft) return; const values = { '[data-if-premise]':createDraft.premise, '[data-if-setting]':createDraft.setting, '[data-if-opening]':createDraft.opening, '[data-if-writing-style]':createDraft.styleId, '[data-if-word-count]':createDraft.wordCount, '[data-if-role-pov]':createDraft.rolePov, '[data-if-user-pov]':createDraft.userPov }; Object.entries(values).forEach(([selector, value]) => { const field = app.querySelector(selector); if (field && value != null) field.value = value; }); const detail = app.querySelector('[data-if-style-detail]'); if (detail && createDraft.stylePrompt) detail.value = createDraft.stylePrompt; }
