  document.addEventListener('click', event => { if (event.target.closest('[data-app-key="ifshikong"]')) { state=readState(); page='home'; activeId=''; render(); app.classList.add('is-open'); return; } if (!app.classList.contains('is-open')) return; if (event.target.closest('[data-if-close]')) { app.classList.remove('is-open'); return; } if (event.target.closest('[data-if-new]')) { page='create'; render(); return; } if (event.target.closest('[data-if-random]')) { randomizeWorld(); return; } if (event.target.closest('[data-if-home]')) { page='home'; activeId=''; render(); return; } if (event.target.closest('[data-if-role-picker]')) { page='role-picker'; render(); return; } if (event.target.closest('[data-if-close-sheet]')) { page='home'; render(); return; } const selectedRole=event.target.closest('[data-if-role]'); if(selectedRole){state.roleId=selectedRole.dataset.ifRole;save();page='home';render();return;} const opened=event.target.closest('[data-if-open]'); if(opened){activeId=opened.dataset.ifOpen;page='detail';render();return;} const deleted=event.target.closest('[data-if-delete]'); if(deleted){state.spaces=state.spaces.filter(item=>item.id!==deleted.dataset.ifDelete);save();page='home';activeId='';render();return;} if(event.target.closest('[data-if-create]')){createSpace();return;} });
