  document.addEventListener('click', event => { if (!app.classList.contains('is-open')) return; const editor = app.querySelector('[data-if-style-editor]'); const detail = app.querySelector('.ifspace-style-detail'); if (event.target.closest('[data-if-style-new]')) { if (detail) detail.hidden = true; if (editor) editor.hidden = false; const name = app.querySelector('[data-if-style-name]'); const prompt = app.querySelector('[data-if-style-prompt]'); if (name) name.value = ''; if (prompt) prompt.value = ''; name?.focus(); return; } if (event.target.closest('[data-if-style-detail-save]')) { saveCurrentWritingStyle(); return; } if (event.target.closest('[data-if-style-close]')) { if (editor) editor.hidden = true; if (detail) detail.hidden = false; return; } if (event.target.closest('[data-if-style-save]')) saveWritingStyle(); });
  document.addEventListener('click', event => { if (!app.classList.contains('is-open')) return; const panel = app.querySelector('.ifspace-type-panel'); if (event.target.closest('[data-if-typography]')) { if (panel) panel.hidden = !panel.hidden; return; } if (event.target.closest('[data-if-typography-close]') && panel) panel.hidden = true; });
  document.addEventListener('click', event => { if (!app.classList.contains('is-open')) return; if (event.target.closest('[data-if-reroll]')) rerollLatestReply(); });
  document.addEventListener('input', event => { if (!app.classList.contains('is-open')) return; if (event.target.matches('[data-if-font-size]')) { const size = Math.max(12, Math.min(32, Number(event.target.value) || 15)); const output = event.target.parentElement?.querySelector('output'); if (output) output.textContent = `${size}px`; saveTypography({ size }); } if (event.target.matches('[data-if-font-color]')) { const color = event.target.value; const output = event.target.parentElement?.querySelector('output'); if (output) output.textContent = color.toUpperCase(); saveTypography({ color }); } });
  document.addEventListener('change', event => { if (!app.classList.contains('is-open')) return; if (event.target.matches('[data-if-font]')) { saveTypography({ font:event.target.value }); return; } if (event.target.matches('[data-if-font-file]')) { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const source = String(reader.result || ''); if (!source) return; saveTypography({ font:'custom', customFontName:file.name.replace(/\.[^.]+$/, ''), customFontSource:source }); render(); const panel = app.querySelector('.ifspace-type-panel'); if (panel) panel.hidden = false; }; reader.onerror = () => window.alert('字体读取失败，请换一个字体文件。'); reader.readAsDataURL(file); } });
